// Callers' conveniences

/// Go: `norm.NFC.String(s)` — the darwin file-name normalization of `hugofs/fileinfo.go`
/// (`normalizeFilename`) and `component_fs.go` (`applyMeta`).
pub fn nfc_string(s: &str) -> String {
    NFC.string(s)
}

/// Go: `norm.NFD.String(s)`.
pub fn nfd_string(s: &str) -> String {
    NFD.string(s)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basics() {
        assert_eq!(VERSION, "15.0.0");
        assert_eq!(nfc_string("cafe\u{301}.md"), "café.md");
        assert_eq!(nfc_string("café.md"), "café.md");
        assert_eq!(nfd_string("café.md"), "cafe\u{301}.md");
        assert_eq!(nfc_string("\u{1100}\u{1161}\u{11a8}"), "\u{ac01}");
        assert_eq!(nfd_string("\u{ac01}"), "\u{1100}\u{1161}\u{11a8}");
        assert_eq!(nfc_string("e\u{327}\u{306}"), "\u{1e1d}");
        assert_eq!(nfc_string("บทความ/ไทย.md"), "บทความ/ไทย.md");
        assert_eq!(nfc_string(""), "");
        // A CGJ after 30 non-starters.
        let s = format!("a{}", "\u{301}".repeat(31));
        assert_eq!(
            nfd_string(&s),
            format!("a{}\u{34f}\u{301}", "\u{301}".repeat(30))
        );
        assert_eq!(NFC.bytes(b"e\xcc\x81\xff"), b"\xc3\xa9\xff");
        assert_eq!(NFC.quick_span("cafe\u{301}".as_bytes()), 3);
        assert_eq!(NFD.properties("\u{301}".as_bytes()).ccc(), 230);
    }
}
